using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
namespace Mcrf.Wpf {public sealed partial class MainWindow {
 Button CompactSettingsLink(string label,Action open){var button=Button(label,open);button.Name="settingsLink"+new string(label.Where(Char.IsLetter).ToArray());StyleCompactButton(button);button.Margin=new Thickness(0,0,0,8);return button;}
 void DetachProfileRecoveryButtons(UIElement tools){foreach(var button in CompactLogicalChildren<Button>(tools).Where(x=>x.Name=="compactCreateBackup"||x.Name=="compactResetProfile").ToArray()){var parent=button.Parent as Panel;if(parent!=null)parent.Children.Remove(button);}}
 UIElement CompactRecoveryButtons(){var backup=AsyncButton("Резервная копия",CreateProfileBackup);backup.Name="compactCreateBackup";var reset=AsyncButton("Сброс/восстановление",ProfileActions);reset.Name="compactResetProfile";foreach(var b in new[]{backup,reset}){StyleCompactButton(b);b.FontSize=11;b.Padding=new Thickness(6);b.MinWidth=0;}var row=new Grid{Margin=new Thickness(0,4,0,4)};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition());backup.Margin=new Thickness(0,0,4,0);reset.Margin=new Thickness(4,0,0,0);Grid.SetColumn(reset,1);row.Children.Add(backup);row.Children.Add(reset);return row;}
 void ConfigureSubscriptionRefresh(Button button){var content=button.Content as Panel;if(content!=null){var icon=content.Children.OfType<FrameworkElement>().FirstOrDefault();if(icon!=null){content.Children.Remove(icon);var badge=new Grid{HorizontalAlignment=HorizontalAlignment.Center};badge.Children.Add(icon);badge.Children.Add(new TextBlock{Name="subscriptionIntervalBadge",Text=SubscriptionIntervalLabel(session.State.SubscriptionUpdateHours),FontSize=9,FontWeight=FontWeights.SemiBold,Padding=new Thickness(2,0,2,0),Background=Brush(CompactSurface),Foreground=Brush(CompactPrimary),HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Bottom,Margin=new Thickness(10,12,-6,-3)});content.Children.Insert(0,badge);}}
 var menu=new ContextMenu();foreach(int hours in new[]{1,3,6,12,24,72,168}){int value=hours;var item=new MenuItem{Header=SubscriptionIntervalLabel(hours),IsCheckable=true,IsChecked=session.State.SubscriptionUpdateHours==hours};item.Click+=async(s,e)=>{int previous=session.State.SubscriptionUpdateHours;await CompactPersist(()=>session.State.SubscriptionUpdateHours=value,()=>session.State.SubscriptionUpdateHours=previous);lastSubscriptionAttempt=DateTime.UtcNow;foreach(MenuItem entry in menu.Items)entry.IsChecked=(int)entry.Tag==session.State.SubscriptionUpdateHours;foreach(var label in CompactLogicalChildren<TextBlock>(button).Where(x=>x.Name=="subscriptionIntervalBadge"))label.Text=SubscriptionIntervalLabel(session.State.SubscriptionUpdateHours);};item.Tag=value;menu.Items.Add(item);}button.ContextMenu=menu;button.ToolTip="Обновить подписки · ПКМ: интервал";}
 static string SubscriptionIntervalLabel(int hours){return hours==0?"—":hours<24?hours+"ч":(hours/24)+"д";}
}}
